@startuml
abstract class User {
  + fullName : string
}

class UnderAgedUser extends User {
  + studentCard : string
}

class AdultUser extends User {
  + idCard : string
}

class Book {
  + title : string
  + author : string
}

class BorrowingHistory {
  + date : date
}

User "1" -- "*" BorrowingHistory : has
BorrowingHistory "*" -- "1" Book : includes

User "0..1" -- "0..4" Book : borrows
@enduml

